#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int a, b;
} Pair;

static inline int next_int(void) {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();

    int value = 0;
    while (c > ' ') {
        value = value * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return value;
}

int main(void) {
    int E = next_int();
    int M = next_int();
    int D = next_int();

    Pair *likes = malloc((size_t)M * sizeof(Pair));
    Pair *dislikes = malloc((size_t)D * sizeof(Pair));
    int *group = calloc((size_t)E + 1, sizeof(int));

    for (int i = 0; i < M; ++i) {
        likes[i].a = next_int();
        likes[i].b = next_int();
    }

    for (int i = 0; i < D; ++i) {
        dislikes[i].a = next_int();
        dislikes[i].b = next_int();
    }

    for (int g = 1; g <= E / 3; ++g) {
        int a = next_int();
        int b = next_int();
        int c = next_int();
        group[a] = group[b] = group[c] = g;
    }

    int violations = 0;

    for (int i = 0; i < M; ++i) {
        if (group[likes[i].a] != group[likes[i].b])
            ++violations;
    }

    for (int i = 0; i < D; ++i) {
        if (group[dislikes[i].a] == group[dislikes[i].b])
            ++violations;
    }

    printf("%d\n", violations);

    free(likes);
    free(dislikes);
    free(group);
    return 0;
}
